// ---------------- поиск нужных слов и фраз ----------------

const norm = (s) => String(s || "").toLowerCase().replace(/ё/g, "е").replace(/[Ӏӏ1|]/g, "ӏ");
const wordsOf = (s) => norm(s).match(/[а-яӏ]+/g) || [];

// Основа русского слова: без типичных окончаний (идти → ид, утро → утр, хороший → хорош).
const RU_END = /(ться|тись|ешь|ешься|ать|ять|ить|еть|уть|ыть|оть|ти|ся|сь|ый|ий|ой|ая|яя|ое|ее|ые|ие|ую|юю|ого|его|ому|ему|ым|им|ом|ем|ах|ях|ам|ям|ами|ями|ов|ев|ей|а|я|о|е|ы|и|у|ю|ь|й)$/;
function ruStem(w) {
  if (w.length <= 3) return w;
  const s = w.replace(RU_END, "");
  return s.length >= 3 ? s : w.slice(0, 3);
}
// Основа ингушского слова: склонение добавляет окончания (котам → котамашка, нана → нанас).
const inhStem = (w) => (w.length >= 5 ? w.replace(/[аеиоуяэы]$/, "") : w);

function matches(textWords, key, stem) {
  for (const t of textWords) {
    if (t === key) return 2;
    if (key.length <= 2 || !stem) continue;
    // короткие основы — только с коротким окончанием (мир → мире, но не «мир» → «мирный»)
    if (stem.length >= 4 ? t.startsWith(stem) : t.startsWith(stem) && t.length <= stem.length + 2) return 1;
  }
  return 0;
}

// Ингушские слова записи словарика (до скобок, без пояснений).
function inhHeads(inh) {
  return inh
    .split(" — ")[0] // после тире — пояснения и примеры
    .split(/[\/;]/)
    .map((p) => p.replace(/\(.*?\)/g, " ").trim())
    .map((p) => wordsOf(p)[0])
    .filter((w) => w && w.length >= 2);
}
// Русские слова записи (для «есть (кушать)» — только «есть»).
const ruHeads = (ru) => wordsOf(ru.replace(/\(.*?\)/g, " "));

// Записи словарика, слова которых встречаются в тексте. source — язык текста.
function relevantGlossary(text, source, max = 40) {
  const tw = wordsOf(text);
  if (!tw.length) return [];
  const scored = [];
  GLOSSARY.forEach((e, i) => {
    let score = 0;
    if (source === "inh") {
      for (const h of inhHeads(e[1])) score = Math.max(score, matches(tw, h, h.length >= 4 ? inhStem(h) : h));
    } else {
      const heads = ruHeads(e[0]);
      if (heads.length > 1) { // фразы вроде «до свидания»: нужны все слова
        if (heads.every((h) => matches(tw, h, ruStem(h)))) score = 3;
      } else if (heads.length) {
        score = matches(tw, heads[0], ruStem(heads[0]));
      }
    }
    if (score) scored.push({ e, score, i });
  });
  scored.sort((a, b) => b.score - a.score || a.i - b.i);
  return scored.slice(0, max).map((s) => s.e);
}

// Проверенные фразы, отсортированные по похожести на текст (самые похожие — первыми).
function rankedExamples(text, source) {
  const tw = new Set(wordsOf(text).map((w) => (source === "inh" ? inhStem(w) : ruStem(w))).filter((w) => w.length >= 2));
  return EXAMPLES.map((e, i) => {
    const side = source === "inh" ? e[1] : e[0];
    let score = 0;
    for (const w of wordsOf(side)) {
      const s = source === "inh" ? inhStem(w) : ruStem(w);
      if (s.length >= 2 && tw.has(s)) score++;
    }
    return { e, score, i };
  }).sort((a, b) => b.score - a.score || a.i - b.i);
}

const glossLines = (list) => list.map(([ru, inh]) => `${ru} — ${inh}`).join("\n");
const exampleLines = (list) => list.map(([ru, inh]) => `Russian: ${ru}\nIngush: ${inh}`).join("\n\n");

// Блок знаний для промпта. tier: "full" — всё сразу, "compact" — правила кратко и только нужные слова.
function knowledgeBlock(text, source, tier = "full") {
  const rel = relevantGlossary(text, source, tier === "full" ? 40 : 30);
  const ranked = rankedExamples(text, source);
  if (tier !== "full") {
    const ex = ranked.filter((r) => r.score > 0).slice(0, 6).map((r) => r.e);
    return `<ingush_reference>\n${GUIDE_SHORT}\n</ingush_reference>\n\n` +
      (rel.length ? `<glossary>\nRussian — Ingush dictionary entries for words in this text:\n${glossLines(rel)}\n</glossary>\n\n` : "") +
      (ex.length ? `<verified_phrases>\n${exampleLines(ex)}\n</verified_phrases>\n\n` : "");
  }
  // самые похожие фразы ставим в конец, ближе к тексту
  const ex = ranked.slice().reverse().map((r) => r.e);
  return `<ingush_reference>\n${GUIDE}\n</ingush_reference>\n\n` +
    `<glossary>\nRussian — Ingush dictionary of common words (class of the singular / of the plural; мн. = plural form):\n${glossLines(GLOSSARY)}\n</glossary>\n\n` +
    `<verified_phrases>\nCorrect Ingush phrases (checked by the corpus and dictionaries). Reuse their words and grammar:\n\n${exampleLines(ex)}\n</verified_phrases>\n\n` +
    (rel.length ? `<glossary_for_this_text>\n${glossLines(rel)}\n</glossary_for_this_text>\n\n` : "");
}

module.exports = { GUIDE, GUIDE_SHORT, GLOSSARY, EXAMPLES, relevantGlossary, rankedExamples, knowledgeBlock };
